package com.docintegrity.forensics

import java.io.File

/** Loads benchmark fixtures from src/test/resources/fixtures (generated by the scripts in tools/fixtures). */
object Fixtures {
    fun bytes(name: String): ByteArray {
        val s = Fixtures::class.java.classLoader!!.getResourceAsStream("fixtures/$name")
            ?: error("missing fixture $name (run tools/fixtures/generate_fixtures.py)")
        return s.use { it.readBytes() }
    }
    fun names(): List<String> {
        val dir = File(Fixtures::class.java.classLoader!!.getResource("fixtures")!!.toURI())
        return dir.listFiles()!!.filter { it.name.endsWith(".pdf") }.map { it.name }.sorted()
    }
}
